export function fail(message,status=400){throw Object.assign(new Error(message),{status});}
export const cleanText=(v,max=160)=>typeof v==='string'&&v.trim().length&&v.trim().length<=max?v.trim():fail('Please check the highlighted information.');
export const uuid=v=>typeof v==='string'&&/^[a-f0-9-]{36}$/.test(v)?v:fail('Invalid record.');
export function nutrition(v,max=20000){if(v==null||v==='')return null;return typeof v==='number'&&Number.isFinite(v)&&v>=0&&v<=max?v:fail('Check the nutrition amounts.');}
export function mealInput(v){const eatenAt=cleanText(v.eatenAt,40);if(!/^\d{4}-\d\d-\d\dT/.test(eatenAt)||!Number.isFinite(Date.parse(eatenAt)))fail('Choose a valid meal time.');if(v.micros!=null&&(typeof v.micros!=='object'||Array.isArray(v.micros)))fail('Invalid micronutrients.');const micros=Object.fromEntries(['calcium','iron','magnesium','potassium','sodium','zinc','vitaminA','vitaminC','vitaminD','vitaminE','vitaminB12','folate'].map(k=>[k,nutrition(v.micros?.[k],2000000)]));return {id:uuid(v.id),name:cleanText(v.name),portion:cleanText(v.portion,120),calories:nutrition(v.calories),protein:nutrition(v.protein),carbs:nutrition(v.carbs),fat:nutrition(v.fat),micros,nutritionSource:v.nutritionSource==null?null:cleanText(v.nutritionSource,120),eatenAt:new Date(eatenAt).toISOString()};}
export const LOG_BOUNDS={workout:[1,600],water:[1,200],weight:[1,1500]};
export function logInput(v){if(!Object.hasOwn(LOG_BOUNDS,v.kind))fail('Choose workout, water or weight.');const [min,max]=LOG_BOUNDS[v.kind];if(typeof v.value!=='number'||!Number.isFinite(v.value)||v.value<min||v.value>max)fail('Check the logged amount.');const loggedAt=cleanText(v.loggedAt,40);if(!/^\d{4}-\d\d-\d\dT/.test(loggedAt)||!Number.isFinite(Date.parse(loggedAt)))fail('Choose a valid log time.');const detail=v.detail==null?null:cleanText(v.detail,80);return {id:uuid(v.id),kind:v.kind,value:v.value,detail,loggedAt:new Date(loggedAt).toISOString()};}
export function reminderInput(v){const tone=v.tone??'direct',daysPerWeek=v.daysPerWeek??7;if(!TONES.includes(tone))fail('Choose gentle, direct or cheeky.');if(!CADENCES.includes(daysPerWeek))fail('Choose 1, 3, 5 or 7 reminder days.');if(!Object.hasOwn(KINDS,v.kind))fail('Choose a reminder type.');for(const k of ['time','quietStart','quietEnd'])if(typeof v[k]!=='string'||!/^([01]\d|2[0-3]):[0-5]\d$/.test(v[k]))fail('Choose a valid reminder time.');try{new Intl.DateTimeFormat('en',{timeZone:v.timezone}).format();}catch{fail('Choose a valid time zone.');}return {id:uuid(v.id),tone,daysPerWeek,kind:v.kind,time:v.time,timezone:v.timezone,enabled:v.enabled===true?1:0,quietStart:v.quietStart,quietEnd:v.quietEnd};}
