export function isDue(r,now){if(!r.enabled)return false;const l=localTime(now,r.timezone),a=minutes(r.quiet_start),b=minutes(r.quiet_end),t=minutes(l.time);if(!scheduledDay(l.day,r.days_per_week??7))return false;if(a!==b&&(a<b?t>=a&&t<b:t>=a||t<b))return false;const delta=t-minutes(r.time);return delta>=0&&delta<10?l.day:false;}
export function progress(count){return {completedSets:count,xp:count*25,level:1+Math.floor(count/4),unlocks:{shieldBreak:count>=196,ember:count>=4,arc:count>=16,frost:count>=36}};}
export function validateCompletion(w,input,now){const elapsed=(now-w.started_at)/1000,kind=EXERCISES[w.mode]?.kind,min=['hold','pace'].includes(kind)?w.goal:Math.max(2,w.goal*.3);if(elapsed<min||elapsed>7200)fail('This set expired or finished too quickly. Begin a new set.');if(!Number.isFinite(input.value)||input.value<w.goal||input.value>100000)fail('Complete the selected goal first.');if(kind==='pace'&&(!Number.isFinite(input.active)||input.active<w.goal))fail('Hand movement is needed to complete this round.');return true;}

