// npm run build:site -> dist/site/apps/coach/ : the static, local-first build (no server, no sign-in; /api/* is answered from IndexedDB).
// This folder is what gets copied into the site repo (mominc.online/apps/coach/). Nothing here touches the site repo.
import {build} from 'esbuild';
import {cp,mkdir,rm,readFile,writeFile,readdir,stat} from 'node:fs/promises';
import {resolve,join} from 'node:path';
import {pathToFileURL} from 'node:url';
import {prepareReleaseBuild} from './release-build.mjs';

const BASE='/apps/coach/',out=resolve('dist/site/apps/coach');
await rm(out,{recursive:true,force:true});await mkdir(out,{recursive:true});
const id=await prepareReleaseBuild();
const useLocalAuth={name:'local-auth',setup(b){b.onResolve({filter:/auth-client\.mjs$/},()=>({path:resolve('static/local-auth.mjs')}));}};
await build({entryPoints:['launch.mjs'],bundle:true,format:'esm',target:'es2022',minify:true,outfile:join(out,'launch-runtime.mjs'),external:['./nutrition-data.mjs'],plugins:[useLocalAuth]});
await build({entryPoints:['training.mjs'],bundle:true,format:'esm',target:'es2022',minify:true,outfile:join(out,'training-runtime.mjs'),external:['three','three/addons/*']});
// Root-absolute references become relative to the page, which lives at /apps/coach/.
const relative=s=>s.replace(/(['"])\/(food-worker\.mjs|sw\.js|models\/|privacy\.html|source\.json|LICENSE)/g,'$1./$2').replace(/\/pose\.html\?reconnect=/g,'./?reconnect=').replaceAll('/signout-with-chatgpt?return_to=%2Fpose.html','./').replaceAll('/signin.html?return_to=%2Fpose.html','./');
for(const name of ['launch-runtime.mjs','training-runtime.mjs'])await writeFile(join(out,name),relative(await readFile(join(out,name),'utf8')));
await writeFile(join(out,'launch-bootstrap.mjs'),relative(await readFile('launch-bootstrap.mjs','utf8')));
for(const f of ['nutrition-data.mjs','food-worker.mjs','LICENSE'])await cp(f,join(out,f));
await cp('models',join(out,'models'),{recursive:true});
await mkdir(join(out,'icons'));
for(const f of ['coach-2d-192.png','coach-2d-512.png','coach-2d-maskable.png','coach-2d-apple.png','mom-inc-mark-96.webp'])await cp(join('icons',f),join(out,'icons',f));
await cp('static/privacy.html',join(out,'privacy.html'));

// index.html: same page, one stylesheet, relative URLs, static flag.
let page=(await readFile('pose.html','utf8')).replaceAll('startup-recovery-1',id);
const links=[...page.matchAll(/<link[^>]*rel="stylesheet"[^>]*href="([^"?]+)[^"]*"[^>]*>/g)];
const css=(await Promise.all(links.map(m=>readFile('.'+m[1],'utf8')))).join('\n')+'\n#signIn,#homeSignIn,#signOut,#releaseEmailForm{display:none!important}\n';
await writeFile(join(out,'app.css'),css);
for(const m of links)page=page.replace(m[0],'');
page=page.replace('<link rel="manifest" href="/manifest.webmanifest?v=myr5-simple-v1">',`<script>window.MYR5_STATIC=true;</script><link rel="stylesheet" href="app.css?v=${id}"><link rel="manifest" href="manifest.webmanifest?v=${id}">`)
 .replace(/(href|src)="\/(?!\/)/g,'$1="./').replace('./pose.html','./');
await writeFile(join(out,'index.html'),page);
await writeFile(join(out,'manifest.webmanifest'),JSON.stringify({id:BASE,name:"MOM's: Coach MYR5",short_name:"MOM's: MYR5",description:'Food, workouts, reminders and goals. Everything stays on this phone.',start_url:BASE,scope:BASE,display:'standalone',background_color:'#21172f',theme_color:'#21172f',icons:[{src:'icons/coach-2d-192.png',sizes:'192x192',type:'image/png',purpose:'any'},{src:'icons/coach-2d-512.png',sizes:'512x512',type:'image/png',purpose:'any'},{src:'icons/coach-2d-maskable.png',sizes:'512x512',type:'image/png',purpose:'maskable'}]}));

// release.json: the update check fetches this with cache:'no-cache'.
const {RELEASE}=await import(pathToFileURL(resolve('release-info.mjs')).href);
await writeFile(join(out,'release.json'),JSON.stringify({...RELEASE,url:BASE}));

// sw.js: own cache prefix (the origin is shared with other apps), own scope, precache = exactly what was built.
const walk=async(dir,pre='')=>(await Promise.all((await readdir(dir,{withFileTypes:true})).map(e=>e.isDirectory()?walk(join(dir,e.name),pre+e.name+'/'):[pre+e.name]))).flat();
const built=(await walk(out)).filter(f=>!/^(models\/|sw\.js$|index\.html$|release\.json$|LICENSE$)/.test(f)&&f!=='source.json');
const core=['',...['manifest.webmanifest','launch-bootstrap.mjs','launch-runtime.mjs','app.css','icons/coach-2d-192.png','icons/mom-inc-mark-96.webp']].map(f=>BASE+f);
const files=[...new Set([...core,...built.map(f=>BASE+f)])];
let sw=(await readFile('sw.js','utf8')).replaceAll('myr5-shell-','myr5-coach-shell-').replace(/^const SHELL='[^']*'/,`const SHELL='myr5-coach-shell-${id}'`)
 .replace(/const FILES=\[.*?\];/s,`const FILES=${JSON.stringify(files)};`).replace(/const CORE=\[.*?\];/s,`const CORE=${JSON.stringify(core)};`)
 .replaceAll('for(const client of all)if(new URL(client.url).origin===url.origin)',`for(const client of all)if(new URL(client.url).origin===url.origin&&new URL(client.url).pathname.startsWith('${BASE}'))`)   // shared origin: never hijack another app's tab
