 .replaceAll("'/pose.html'",`'${BASE}'`).replaceAll("'/icons/",`'${BASE}icons/`);
await writeFile(join(out,'sw.js'),sw);

// The AGPL source offer travels with the app.
const sources={};for(const folder of ['server','db','scripts','scheduler','static'])for(const e of await readdir(folder))if(/\.(mjs|ts|cjs|html)$/.test(e))sources[`${folder}/${e}`]=await readFile(`${folder}/${e}`,'utf8');
