await writeFile(join(out,'source.json'),JSON.stringify(sources));
const size=async d=>(await Promise.all((await readdir(d,{withFileTypes:true})).map(async e=>e.isDirectory()?size(join(d,e.name)):(await stat(join(d,e.name))).size))).reduce((a,b)=>a+b,0);
console.log(`built ${out}: ${((await size(out))/1048576).toFixed(2)} MB, build ${id}`);

