export default {
  async scheduled(_event, env, ctx) {
    ctx.waitUntil((async () => {
      const response = await fetch(new URL('/api/cron', env.SITE_ORIGIN), {
        method: 'POST',
        headers: { Authorization: `Bearer ${env.CRON_SECRET}` },
        signal: AbortSignal.timeout(10000),
      });
      if (!response.ok) throw new Error(`Basic reminder tick failed: HTTP ${response.status}`);
      const result = await response.json();
      if (result.configured !== true) throw new Error('Basic reminder sender is unconfigured');
    })());
  },
};

