 // Lets the optional background-reminder sync mirror reminder changes (no import cycle with local-reminders).
 if(r.ok&&options.method&&options.method!=='GET'&&/^\/api\/(reminders|account)/.test(path))globalThis.dispatchEvent?.(new Event('myr5:reminders-changed'));
 return r;
};
