// Static build reminders: no server, no push. While the app is open an in-page timer fires due reminders (service-worker
// notification when allowed, plus an in-app banner); opening the app later catches up anything still inside its 10-minute window.
// One notification per reminder per day, plain text only. Nothing here escalates or repeats.
import {isDue} from '../server/domain.mjs';
import {reminderMessage} from '../reminder-settings.mjs';
import {backend} from './local-auth.mjs';
import {enablePush,disablePush,resumePush,pushActive,webStorage} from './push-sync.mjs';
export const APP_TITLE="MOM's: Coach MYR5";
const FLAG='myr5-coach-notify';
const read=()=>{try{return localStorage.getItem(FLAG)==='1';}catch{return false;}};
export const notificationsOn=()=>'Notification' in window&&Notification.permission==='granted'&&read();
const storage=webStorage(),push={reg:()=>navigator.serviceWorker?.getRegistration(),reminders:()=>backend.list('reminders'),supported:()=>'PushManager' in window&&'serviceWorker' in navigator};
let pushNote='';
export const backgroundOn=()=>notificationsOn()&&pushActive(storage);
export const statusText=()=>!('Notification' in window)?'This browser cannot show notifications.':!notificationsOn()?'Off on this phone':backgroundOn()?'On. Reminders also arrive when the app is closed.':'On. Reminders show while the app is open.'+(pushNote?' '+pushNote:'');
// Background delivery is best effort on top of the local reminders: any failure leaves notifications on, local only, with a note.
export async function setNotifications(on){
 pushNote='';
 if(!on){try{localStorage.removeItem(FLAG);}catch{}await disablePush({reg:await push.reg(),storage}).catch(()=>{});return false;}
 if(!('Notification' in window))throw Error('This browser cannot show notifications.');
 if(await Notification.requestPermission()!=='granted')throw Error('Not allowed. Enable notifications in Settings.');
 try{localStorage.setItem(FLAG,'1');}catch{}
 try{await enablePush({reg:await push.reg(),storage,fetchImpl:(...a)=>fetch(...a),reminders:push.reminders,supported:push.supported()});}catch(e){pushNote=e.message;}
 return true;
}
async function show(title,body,tag,panel,force=true){
 if(!force&&backgroundOn())return false;   // the Worker's push is the system notice; the in-app banner still shows
 const reg=await navigator.serviceWorker?.getRegistration();
 if(!reg||Notification.permission!=='granted')return false;
 await reg.showNotification(title,{body,tag,icon:'./icons/coach-2d-192.png',badge:'./icons/coach-2d-192.png',data:{url:new URL('./?panel='+panel,document.baseURI).pathname+'?panel='+panel},renotify:false});return true;
}
export const testNotification=()=>show(APP_TITLE,'Your phone is connected to reminders.','myr5-test','reminders');
function banner(text){
 let el=document.getElementById('reminderBanner');
 if(!el){el=document.createElement('aside');el.id='reminderBanner';el.setAttribute('role','status');el.popover='manual';el.style.cssText='position:fixed;inset:12px 12px auto 12px;margin:0;width:auto;height:auto;padding:12px;border-radius:12px;background:#2b1f3d;color:#f5e4ba;border:1px solid #d6bddf';const b=document.createElement('button');b.type='button';b.textContent='Dismiss';b.onclick=()=>el.hidePopover();el.append(document.createElement('span'),' ',b);document.body.append(el);}
 el.firstChild.textContent=text;if(el.matches(':popover-open'))el.hidePopover();el.showPopover();// re-shown so it stays above any open dialog
}
const notifyBrowser=async(r,text,key)=>{banner(text);try{await show(APP_TITLE,text,key,r.kind==='meal'?'meals':'reminders',false);}catch{}};
export async function tick(now=Date.now(),{store=backend,notify=notifyBrowser}={}){
 const fired=[];
 for(const r of await store.list('reminders')){
  const day=isDue(r,now);if(!day)continue;
  const key=`${r.id}:${day}:${r.time}`;if(await store.get('fired',key))continue;
  await store.put('fired',key,{at:now,kind:r.kind});
  const text=reminderMessage(r.kind,r.tone);fired.push({key,kind:r.kind,text});await notify(r,text,key);
 }
 return fired;
}
export function startReminders(){
 const sync=async()=>{if(notificationsOn())await resumePush({reg:await push.reg(),storage,fetchImpl:(...a)=>fetch(...a),reminders:push.reminders}).catch(()=>{});};
 let timerSync;window.addEventListener('myr5:reminders-changed',()=>{clearTimeout(timerSync);timerSync=setTimeout(sync,500);});sync();
 const run=()=>{tick().catch(()=>{});};
 run();const timer=setInterval(()=>{if(!document.hidden)run();},15000);
 document.addEventListener('visibilitychange',()=>{if(!document.hidden)run();});window.addEventListener('online',run);
 window.addEventListener('pagehide',()=>clearInterval(timer));
}

