// Static (no-server) build: the /api/* calls the UI makes are answered here from IndexedDB, keeping the server's row shapes.
// createApi(backend) is pure (tests pass an in-memory backend); idbBackend() is the real on-device store.
import {uuid,fail,mealInput,logInput,reminderInput} from '../server/domain.mjs';
import {validateOnboarding,dailyTargets,calendarDay} from '../onboarding-domain.mjs';
const COLLECTIONS=['meals','logs','reminders','kv','fired'];
const USER='local';

export function memoryBackend(){
 const data=Object.fromEntries(COLLECTIONS.map(c=>[c,new Map()]));
 return {async list(c){return [...data[c].values()].map(v=>structuredClone(v));},async get(c,k){const v=data[c].get(k);return v===undefined?undefined:structuredClone(v);},async put(c,k,v){data[c].set(k,structuredClone(v));},async del(c,k){data[c].delete(k);},async clear(){for(const m of Object.values(data))m.clear();}};
}

export function idbBackend(name='myr5-coach-local'){
 let dbp;
 const open=()=>dbp??=new Promise((resolve,reject)=>{const r=indexedDB.open(name,1);r.onupgradeneeded=()=>{for(const c of COLLECTIONS)r.result.createObjectStore(c);};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});
 const tx=async(c,mode,fn)=>{const db=await open();return new Promise((resolve,reject)=>{const t=db.transaction(c,mode),s=t.objectStore(c);let out;const q=fn(s);if(q)q.onsuccess=()=>{out=q.result;};t.oncomplete=()=>resolve(out);t.onerror=t.onabort=()=>reject(t.error);});};
 return {list:c=>tx(c,'readonly',s=>s.getAll()),get:(c,k)=>tx(c,'readonly',s=>s.get(k)),put:(c,k,v)=>tx(c,'readwrite',s=>s.put(v,k)),del:(c,k)=>tx(c,'readwrite',s=>s.delete(k)),async clear(){for(const c of COLLECTIONS)await tx(c,'readwrite',s=>s.clear());}};
}

const rowMeal=(v,now)=>({id:v.id,user_id:USER,name:v.name,portion:v.portion,calories:v.calories,protein:v.protein,carbs:v.carbs,fat:v.fat,eaten_at:v.eatenAt,created_at:now,micros:JSON.stringify(v.micros),nutrition_source:v.nutritionSource});
const rowReminder=v=>({id:v.id,user_id:USER,kind:v.kind,time:v.time,timezone:v.timezone,enabled:v.enabled,quiet_start:v.quietStart,quiet_end:v.quietEnd,tone:v.tone,days_per_week:v.daysPerWeek});
const json=(value,status=200)=>new Response(JSON.stringify(value),{status,headers:{'Content-Type':'application/json'}});

export function createApi(backend,{release=async()=>({}),now=()=>Date.now()}={}){
 const readOnboarding=async t=>{const row=await backend.get('kv','onboarding');return row?{data:row.data,startDay:row.startDay,completedAt:row.completedAt,revision:row.revision,targets:dailyTargets(row.data.profile,row.startDay,t)}:null;};
 async function route(path,method,body,t){
  const u=new URL(path,'http://local'),p=u.pathname;
  if(p==='/api/releases/current'&&method==='GET')return release();
  if(p==='/api/account'&&method==='GET'){const onboarding=await readOnboarding(t);return {user:{id:USER,email:'This device',provider:'local'},profile:{},revision:onboarding?.revision||0,onboarding,progress:{},push:{configured:false,publicKey:null,schedulerActive:true,environment:'live'},syncedAt:t};}
  if(p==='/api/onboarding'&&method==='PUT'){
   const cur=await backend.get('kv','onboarding');
   if(!Number.isSafeInteger(body.revision)||body.revision<0)fail('Refresh your coach settings before saving.');
   if(body.revision!==(cur?.revision||0))fail('Coach settings changed in another tab. Refresh before saving again.',409);
   const data=validateOnboarding(body.data);
   await backend.put('kv','onboarding',{data,startDay:cur?.startDay??calendarDay(t,data.profile.timezone),completedAt:cur?.completedAt??t,revision:(cur?.revision||0)+1});
   return {onboarding:await readOnboarding(t),appearance:{}};
  }
  if(p==='/api/export'&&method==='GET'){const o=await backend.get('kv','onboarding');return {onboarding:o?[{data:JSON.stringify(o.data),start_day:o.startDay,completed_at:o.completedAt,revision:o.revision}]:[],meals:await backend.list('meals'),reminders:await backend.list('reminders'),logs:await backend.list('logs')};}
  if(p==='/api/account'&&method==='DELETE'){if(body.confirm!=='DELETE')fail('Type DELETE to clear your data.');await backend.clear();return {deleted:true};}
  // Everything below needs the goals to exist first, as on the server.
  if(['/api/meals','/api/logs','/api/reminders'].includes(p)&&method!=='GET'&&!await backend.get('kv','onboarding'))fail('Answer the setup questions to start.',403);
  if(p==='/api/meals'&&method==='GET')return {items:(await backend.list('meals')).sort((a,b)=>b.eaten_at.localeCompare(a.eaten_at)).slice(0,100)};
  if(p==='/api/meals'&&method==='POST'){const v=mealInput(body);if(!await backend.get('meals',v.id))await backend.put('meals',v.id,rowMeal(v,t));return {saved:true};}
  if(p.startsWith('/api/meals/')&&method==='DELETE'){await backend.del('meals',uuid(p.split('/').at(-1)));return {deleted:true};}
  if(p==='/api/logs'&&method==='GET'){const days=u.searchParams.has('days')?Number(u.searchParams.get('days')):35;if(!Number.isInteger(days)||days<1||days>400)fail('Choose 1 to 400 days.');const since=new Date(t-days*86400000).toISOString();return {items:(await backend.list('logs')).filter(l=>l.logged_at>=since).sort((a,b)=>b.logged_at.localeCompare(a.logged_at))};}
  if(p==='/api/logs'&&method==='POST'){const v=logInput(body);if(await backend.get('logs',v.id))fail('This log already exists.',409);const item={id:v.id,kind:v.kind,value:v.value,detail:v.detail,logged_at:v.loggedAt};await backend.put('logs',v.id,item);return {item};}
  if(p.startsWith('/api/logs/')&&method==='DELETE'){await backend.del('logs',uuid(p.split('/').at(-1)));return {deleted:true};}
  if(p==='/api/reminders'&&method==='GET')return {items:(await backend.list('reminders')).sort((a,b)=>a.time.localeCompare(b.time))};
  if(p==='/api/reminders'&&method==='POST'){const v=reminderInput(body);if((await backend.list('reminders')).length>=16)fail('Keep up to 16 reminders. Remove one before adding another.');if(!await backend.get('reminders',v.id))await backend.put('reminders',v.id,rowReminder(v));return {saved:true};}
  if(p.startsWith('/api/reminders/')){
   const id=uuid(p.split('/').at(-1)),cur=await backend.get('reminders',id);
   if(method==='DELETE'){await backend.del('reminders',id);return {deleted:true};}
   if(method==='PUT'){const v=reminderInput({...body,id});if(!cur)fail('Reminder not found.',404);await backend.put('reminders',id,rowReminder(v));return {saved:true};}
   if(method==='PATCH'){if(typeof body.enabled!=='boolean')fail('Choose on or off.');if(!cur)fail('Reminder not found.',404);await backend.put('reminders',id,{...cur,enabled:body.enabled?1:0});return {enabled:body.enabled};}
  }
  return null;
 }
 // Returns a fetch-style Response so the UI's existing api() helper works unchanged.
 return async function handle(path,{method='GET',body}={}){
  try{
   const parsed=typeof body==='string'&&body?JSON.parse(body):{};
   const value=await route(path,method,parsed,now());
   return value===null?json({error:'Not available in this app.'},404):json(value);
  }catch(e){return json({error:e.status?e.message:'Could not save on this device. Try again.'},e.status||500);}
 };
}

static/push-sync.mjs:
// Static build, background reminders: subscribe through THIS app's service worker (scope /apps/coach/) and mirror the local reminders to the
// shared adhd-push Worker in its plain `coach` mode (one notice per occurrence, never any follow-ups). Everything here is optional: if push is
// unsupported, denied or the Worker is unreachable, the local foreground reminders keep working unchanged.
import {reminderMessage} from '../reminder-settings.mjs';
export const PUSH_ORIGIN='https://adhd-push.mominc-coach.workers.dev';
const KEY='myr5-coach-push-v1';     // own key: the origin is shared with the 2048 app

export const scheduleId=id=>String(id).replaceAll('-','');            // uuid -> 32 hex, what the Worker accepts
const minutes=s=>Number(s.slice(0,2))*60+Number(s.slice(3));
const quiet=r=>{const a=minutes(r.quiet_start),b=minutes(r.quiet_end),t=minutes(r.time);return a!==b&&(a<b?t>=a&&t<b:t>=a||t<b);};
// The Worker has once/daily/weekdays and no quiet hours: anything else stays local-only rather than firing when the user said not to.
export function scheduleBody(r,now=Date.now()){
 const recur=r.days_per_week===7?'daily':r.days_per_week===5?'weekdays':null;
 if(!recur||quiet(r))return null;
 return {app:'coach',id:scheduleId(r.id),time:r.time,tz:r.timezone,recur,label:reminderMessage(r.kind,r.tone),enabled:!!r.enabled,revision:Math.floor(now/1000),followups:false};
}
const same=b=>JSON.stringify({...b,revision:0});
/** What to send: only reminders whose content changed since the last successful sync, and disables for ones that were deleted or became local-only. */
export function planSync(reminders,synced,now=Date.now()){
 const bodies=reminders.map(r=>scheduleBody(r,now)).filter(Boolean),ids=new Set(bodies.map(b=>b.id));
 return {puts:bodies.filter(b=>synced[b.id]!==same(b)),removes:Object.keys(synced).filter(id=>!ids.has(id))};
}

export const webStorage=()=>({get:()=>{try{return JSON.parse(localStorage.getItem(KEY));}catch{return null;}},set:v=>{try{localStorage.setItem(KEY,JSON.stringify(v));}catch{}}});
const fromBase64=t=>Uint8Array.from(atob(t.replace(/-/g,'+').replace(/_/g,'/').padEnd(Math.ceil(t.length/4)*4,'=')),c=>c.charCodeAt(0));

export function workerApi({creds,fetchImpl=fetch,origin=PUSH_ORIGIN}){
 const call=async(method,path,body,auth=true)=>{
  const headers={'content-type':'application/json',...(auth?{'x-install-id':creds().installId,'x-install-secret':creds().secret}:{})};
  const r=await fetchImpl(origin+path,{method,headers,body:body?JSON.stringify(body):undefined});
  if(!r.ok)throw Object.assign(Error('Reminder service '+r.status),{status:r.status});
  return r.json();
 };
 return {install:()=>call('POST','/v1/install',null,false),vapid:()=>call('GET','/v1/vapid',null,false),putSubscription:s=>call('PUT','/v1/subscription',s),deleteSubscription:()=>call('DELETE','/v1/subscription'),putSchedule:b=>call('PUT','/v1/schedule',b),deleteSchedule:id=>call('DELETE','/v1/schedule/'+id)};
}

/** Mirror local reminders to the Worker. A failed call keeps that reminder "unsynced" so the next change or app open retries it. */
export async function runSync({reminders,state,api,save,now=Date.now()}){
 const {puts,removes}=planSync(reminders,state.synced,now);
 for(const b of puts){try{await api.putSchedule(b);state.synced[b.id]=same(b);}catch(e){if(e.status===401)throw e;}}
 for(const id of removes){try{await api.deleteSchedule(id);delete state.synced[id];}catch(e){if(e.status===404)delete state.synced[id];else if(e.status===401)throw e;}}
 save(state);return {puts:puts.length,removes:removes.length};
}

const stateOf=storage=>{const v=storage.get();return v&&v.installId&&v.secret?{synced:{},...v}:null;};
