 let sub=await reg.pushManager.getSubscription(),made=false;
 try{
  if(!state){const i=await api.install();state={installId:i.installId,secret:i.secret,synced:{}};}
  if(!sub){const {publicKey}=await api.vapid();sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:fromBase64(publicKey)});made=true;}
  await api.putSubscription(sub.toJSON());
