 }
}
export async function disablePush({reg,storage,fetchImpl}){
 const state=stateOf(storage);if(!state)return;
 const api=workerApi({creds:()=>state,fetchImpl});
 try{await api.deleteSubscription();}catch{}
 try{await (await reg?.pushManager?.getSubscription())?.unsubscribe();}catch{}
 storage.set({...state,on:false,synced:{}});
}
/** On app open / reminder edits: keep the subscription and the mirrored reminders current. Silent; failures fall back to local reminders. */
export async function resumePush({reg,storage,fetchImpl,reminders,now}){
 const state=stateOf(storage);if(!state?.on)return false;
 const sub=await reg?.pushManager?.getSubscription();
 const api=workerApi({creds:()=>state,fetchImpl});
 try{
  if(!sub){storage.set({...state,on:false});return false;}      // revoked in browser settings: fall back to local only
  await runSync({reminders:await reminders(),state,api,save:storage.set,now});return true;
 }catch(e){if(e.status===401)storage.set(null);return false;}
}

