}
export class CoachVoice {
 constructor(caption,onMode=()=>{}){
  this.caption=caption;this.onMode=onMode;this.enabled=true;this.queue=[];this.current=null;this.epoch=0;
  this.synth=globalThis.speechSynthesis;this.available=!!this.synth;this.unlocked=false;this._voice=null;
