   const utterance=new SpeechSynthesisUtterance(item.text);
   const voice=this.pickVoice();if(voice)utterance.voice=voice;
   utterance.onend=finish;utterance.onerror=finish;
   // Some engines never fire onend; don't let one lost utterance silence every later count.
   item.timer=setTimeout(()=>{if(epoch===this.epoch){this.synth.cancel();finish();}},Math.max(8000,3000+item.text.length*120));
   this.synth.speak(utterance);
  }catch{finish();}
