for(const [id,name,detector,extra] of [['march','Easy march','march',{}],['high-march','High-knee march','march',{lift:.4}],['jogging','Jog in place','march',{}],['step-jack','Step jack','jack',{step:true}],['jumping-jack','Jumping jack','jack',{}]])
