launch.mjs:
import {initAppUpdates} from './app-updates.mjs';
import {BUILD_ID} from './release-build.mjs';
import {authFetch,signOut} from './auth-client.mjs';
import {mountLaunch} from './launch-shell.mjs?v=simple-v1';
import {mountMealNutrition} from './meal-nutrition.mjs';
import {mountMealScanner} from './meal-scanner.mjs';
import {MACROS,MICROS,displayNutrient} from './nutrition.mjs';
import {notificationBinding} from './device-notifications.mjs';
import {FIELDS} from './onboarding-domain.mjs';
import {streak,todayTotals,last7Days,weightSummary} from './simple-progress.mjs';
mountLaunch();
const mealNutrition=mountMealNutrition();
mountMealScanner();
let editingReminder=null;
const $=id=>document.getElementById(id);
let account=null,revision=0,registration=null,installPrompt=null,deviceBusy=false,goalsGate=false;
let logsCache=[],mealsCache=[];
const deviceBinding=notificationBinding(api);
const set=(id,text)=>$(id).textContent=text;
const badge=text=>{set('syncBadge',text);$('syncBadge').hidden=/^(Synced|Connecting…)$/.test(text);};
export async function api(path,method='GET',data){const response=await authFetch(path,{method,credentials:'same-origin',headers:data?{'Content-Type':'application/json'}:undefined,body:data?JSON.stringify(data):undefined,cache:'no-store'});if(response.redirected||!response.headers.get('content-type')?.includes('application/json'))throw Error('Sign in again.');const value=await response.json();if(!response.ok)throw Object.assign(Error(value.error||'Please try again.'),{status:response.status,code:value.code});return value;}
const button=(text,fn)=>{const b=document.createElement('button');b.type='button';b.textContent=text;b.onclick=fn;return b;};
function download(data,name,type='application/json'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([data],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
const localDay=(when,timezone)=>new Intl.DateTimeFormat('en-CA',{timeZone:timezone,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(when));

// --- Goals sheet (setup gate when signed in with no onboarding yet) ---
function populateGoals(){
 const form=$('goalsForm');
 if(!form.elements.goal.options.length)for(const opt of FIELDS.find(f=>f.key==='goal').options){const o=document.createElement('option');o.value=opt;o.textContent=opt;form.elements.goal.append(o);}
 const profile=account?.onboarding?.data?.profile;
 if(profile){form.elements.goal.value=profile.goal;form.elements.goalWeightLbs.value=profile.goalWeightLbs;form.elements.sessionMinutes.value=profile.sessionMinutes;}
}
function openGoalsGate(){goalsGate=true;populateGoals();set('goalsTitle','Set your goals');$('closeGoals').hidden=true;if(!$('goalsPanel').open)$('goalsPanel').showModal();}
function closeGoalsGate(){goalsGate=false;set('goalsTitle','Goals');$('closeGoals').hidden=false;if($('goalsPanel').open)$('goalsPanel').close();}
$('goalsPanel').addEventListener('cancel',e=>{if(goalsGate)e.preventDefault();});
$('goalsForm').onsubmit=async e=>{
 e.preventDefault();const submit=e.target.querySelector('[type=submit]');submit.disabled=true;
 try{
  const form=new FormData(e.target);
  await api('/api/onboarding','PUT',{revision,data:{setupMode:'simple',profile:{goal:form.get('goal'),goalWeightLbs:Number(form.get('goalWeightLbs')),sessionMinutes:Number(form.get('sessionMinutes')),timezone:Intl.DateTimeFormat().resolvedOptions().timeZone}}});
  closeGoalsGate();set('goalsStatus','');
  await refresh();
 }catch(err){set('goalsStatus',err.message);}finally{submit.disabled=false;}
};

// --- Home: Today card + list, streak header ---
function logLabel(l){return l.kind==='workout'?`${l.detail||'Workout'} · ${l.value} min`:l.kind==='water'?`Water · ${l.value} oz`:`Weight · ${l.value} lb`;}
function meter(id,readoutId,value,max,unit,unitSpoken,label){
 const el=$(id),met=max>0&&value>=max;el.max=1;el.value=max>0?Math.min(1,value/max):0;el.dataset.met=String(met);
 el.setAttribute('aria-label',`${label}, ${Math.round(value)} of ${Math.round(max)} ${unitSpoken}`);
 set(readoutId,`${Math.round(value)} / ${Math.round(max)} ${unit}`);
}
function renderTodayList(timezone){
 const today=localDay(Date.now(),timezone);
 const items=[
  ...mealsCache.filter(m=>localDay(m.eaten_at,timezone)===today).map(m=>({time:m.eaten_at,text:`${m.name} · ${Math.round(m.calories||0)} kcal`,remove:()=>api('/api/meals/'+m.id,'DELETE')})),
  ...logsCache.filter(l=>localDay(l.logged_at,timezone)===today).map(l=>({time:l.logged_at,text:logLabel(l),remove:()=>api('/api/logs/'+l.id,'DELETE')})),
 ].sort((a,b)=>Date.parse(b.time)-Date.parse(a.time));
 $('todayList').replaceChildren();
 if(!items.length){set('todayList','Nothing logged yet today.');return;}
 for(const item of items){
  const row=document.createElement('div');row.className='entry';
  const text=document.createElement('span');text.textContent=item.text;
  row.append(text,button('Remove',async()=>{try{await item.remove();await loadToday();}catch(e){badge(e.message);}}));
  $('todayList').append(row);
 }
}
function renderProgress(timezone,targets,profile){
 set('progressStreak',String(streak(logsCache,{timezone})));
 const days=last7Days(logsCache,mealsCache,{sessionMinutes:profile.sessionMinutes,proteinGrams:targets.proteinGrams,waterOz:targets.waterOz},{timezone});
 $('week7').replaceChildren();
 for(const d of days){
  const row=document.createElement('div');row.className='week-day';
  const label=document.createElement('span');label.textContent=new Date(d.day+'T12:00:00Z').toLocaleDateString(undefined,{weekday:'short'});
  row.append(label);
  for(const key of ['workout','protein','water']){const dot=document.createElement('i');dot.className='week-dot';dot.dataset.met=String(d[key]);dot.setAttribute('aria-label',`${key}${d[key]?' met':' not met'} on ${d.day}`);row.append(dot);}
  $('week7').append(row);
 }
 const w=weightSummary(logsCache);
 if(document.activeElement!==$('weightForm').elements.weight)$('weightForm').elements.weight.value=w.latest??'';
 const toGoal=w.latest!=null&&profile.goalWeightLbs!=null?Math.round((profile.goalWeightLbs-w.latest)*10)/10:null;
 set('weightSummary',w.latest==null?'No weight logged yet.':`${w.latest} lb`+(w.changeOverDays!=null?` · ${w.changeOverDays>0?'+':''}${w.changeOverDays} lb in 30 days`:'')+(toGoal!=null?` · ${Math.abs(toGoal)} lb to goal`:''));
}
async function loadToday(){
 if(!account?.onboarding)return;
 const timezone=account.onboarding.data.profile.timezone||Intl.DateTimeFormat().resolvedOptions().timeZone;
 try{const [logsRes,mealsRes]=await Promise.all([api('/api/logs?days=35'),api('/api/meals')]);logsCache=logsRes.items;mealsCache=mealsRes.items;}catch{return;}
 const targets=account.onboarding.targets,profile=account.onboarding.data.profile;
 const totals=todayTotals(logsCache,mealsCache,{timezone});
 meter('proteinMeter','proteinReadout',totals.proteinGrams,targets.proteinGrams||0,'g','grams','Protein');
 meter('waterMeter','waterReadout',totals.waterOz,targets.waterOz||0,'oz','ounces','Water');
 meter('workoutMeter','workoutReadout',totals.workoutMinutes,profile.sessionMinutes||0,'min','minutes','Workout');
 set('streakReadout','🔥 '+streak(logsCache,{timezone})+' DAY STREAK');
 renderTodayList(timezone);
 renderProgress(timezone,targets,profile);
}
$('logWater').onclick=async()=>{$('logWater').disabled=true;try{await api('/api/logs','POST',{id:crypto.randomUUID(),kind:'water',value:8,loggedAt:new Date().toISOString()});await loadToday();}catch(e){badge(e.message);}finally{$('logWater').disabled=false;}};
async function logWorkout(minutes){
 set('logWorkoutStatus','');
 try{await api('/api/logs','POST',{id:crypto.randomUUID(),kind:'workout',value:minutes,loggedAt:new Date().toISOString()});$('logWorkoutPanel').close();$('logWorkoutForm').reset();await loadToday();}
 catch(e){set('logWorkoutStatus',e.message);}
}
for(const b of document.querySelectorAll('#workoutPresets [data-minutes]'))b.onclick=()=>logWorkout(Number(b.dataset.minutes));
$('logWorkoutForm').onsubmit=async e=>{e.preventDefault();await logWorkout(Number(new FormData(e.target).get('minutes')));};

// --- Train (camera training; lazily loaded so Home never downloads three.js/MediaPipe/models) ---
async function onSetComplete({detail,minutes}){
 try{await api('/api/logs','POST',{id:crypto.randomUUID(),kind:'workout',value:minutes,detail,loggedAt:new Date().toISOString()});await loadToday();}
 catch(e){badge(e.message);}
}
let training=null;
$('openTraining').onclick=async()=>{
 $('openTraining').disabled=true;
 try{if(!training){const {mountTraining}=await import(/* @vite-ignore */new URL('training-runtime.mjs?v='+BUILD_ID,import.meta.url).href);training=mountTraining({onSetComplete});}training.open();}
 catch(e){badge(e.message);}
 finally{$('openTraining').disabled=false;}
};
$('weightForm').onsubmit=async e=>{
 e.preventDefault();const submit=e.target.querySelector('[type=submit]');submit.disabled=true;
 try{await api('/api/logs','POST',{id:crypto.randomUUID(),kind:'weight',value:Number(new FormData(e.target).get('weight')),loggedAt:new Date().toISOString()});set('weightStatus','Saved.');await loadToday();}
 catch(err){set('weightStatus',err.message);}finally{submit.disabled=false;}
};

// --- Account sync ---
async function refresh(){
 try{
  const value=await api('/api/account');account=value;revision=value.revision;
  $('homeSignIn').hidden=true;$('signIn').hidden=true;$('accountContent').hidden=false;$('accountSettingsContent').hidden=false;
  set('accountName',value.user.provider==='clerk'?(window.Clerk?.user?.primaryEmailAddress?.emailAddress||value.user.email):value.user.email);
  set('accountStatus','Progress synced');badge('Synced');
  set('pushStatus',value.push.environment==='preview'?'Preview only. Open the live app for reminders.':value.push.schedulerActive?'Reminders on. Turn on this phone below.':'Reconnecting…');
  await syncDeviceSwitch();
  if(!value.onboarding){$('todayCard').hidden=true;$('todayList').replaceChildren();openGoalsGate();}
  else{if(goalsGate)closeGoalsGate();$('todayCard').hidden=false;await loadToday();}
  return value;
 }catch(e){
  if(e.status===401){
   account=null;$('homeSignIn').hidden=false;$('signIn').hidden=false;$('accountContent').hidden=true;$('accountSettingsContent').hidden=true;
   $('mealList').replaceChildren();$('reminderList').replaceChildren();$('todayCard').hidden=true;$('todayList').replaceChildren();
   await syncDeviceSwitch();set('accountName','Sign in to sync');badge('Sign in to save progress');
  }else{
   badge(navigator.onLine?e.message:'Offline · reconnect to sync');
   if(!account)set('todayList',navigator.onLine?'Couldn’t connect. Pull to refresh.':'You’re offline. Reconnect to see today.');
  }
  return null;
 }
}

// --- Food ---
const localDatetime=()=>{const d=new Date();return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);};
$('mealForm').elements.eatenAt.value=localDatetime();
function mealPayload(item){const micros=typeof item.micros==='string'?JSON.parse(item.micros):item.micros||{};return {name:item.name,portion:item.portion,calories:item.calories,protein:item.protein,carbs:item.carbs,fat:item.fat,micros,nutritionSource:item.nutrition_source};}
function renderRecentMeals(items){
 const seen=new Set(),recent=[];
 for(const item of items){if(seen.has(item.name))continue;seen.add(item.name);recent.push(item);if(recent.length>=6)break;}
 $('recentMeals').replaceChildren();$('recentMeals').hidden=!recent.length;
 for(const item of recent){
  const b=button(item.name,async()=>{b.disabled=true;try{await api('/api/meals','POST',{...mealPayload(item),id:crypto.randomUUID(),eatenAt:new Date().toISOString()});set('mealStatus','');$('mealsPanel').close();await meals();await loadToday();}catch(e){set('mealStatus',e.message);}finally{b.disabled=false;}});
  $('recentMeals').append(b);
 }
}
async function meals(){try{const {items}=await api('/api/meals');$('mealList').replaceChildren();if(!items.length)set('mealList','No meals logged yet.');for(const item of items){
 const row=document.createElement('div');row.className='entry';const text=document.createElement('details'),name=document.createElement('summary');name.textContent=item.name;text.append(name);
 const detail=document.createElement('small');detail.textContent=item.portion+' · '+new Date(item.eaten_at).toLocaleString();text.append(detail);
 const breakdown=document.createElement('div');breakdown.className='saved-nutrients';const micros=typeof item.micros==='string'?JSON.parse(item.micros):item.micros||{};
 for(const [label,keys,values] of [['Macros',MACROS,item],['Micros',MICROS,micros]]){const p=document.createElement('p');p.textContent=label+': '+keys.map(([k,title,unit])=>title+' '+displayNutrient(values[k],unit)).join(' · ');breakdown.append(p);}text.append(breakdown);
 row.append(text,button('Remove',async()=>{try{await api('/api/meals/'+item.id,'DELETE');await meals();await loadToday();}catch(e){set('mealStatus',e.message);}}));$('mealList').append(row);}
 renderRecentMeals(items);
}catch(e){set('mealList',e.message);}}
$('mealForm').onsubmit=async e=>{e.preventDefault();const form=e.target,submit=form.querySelector('[type=submit]');submit.disabled=true;const d={...Object.fromEntries(new FormData(form)),...mealNutrition.data()};try{d.id=crypto.randomUUID();d.eatenAt=new Date(d.eatenAt).toISOString();await api('/api/meals','POST',d);set('mealStatus','');mealNutrition.reset();form.elements.eatenAt.value=localDatetime();$('mealsPanel').close();await meals();await loadToday();}catch(err){set('mealStatus',err.message);}finally{submit.disabled=false;}};

// --- Reminders ---
async function reminders(){try{
 const {items}=await api('/api/reminders');$('reminderList').replaceChildren();if(!items.length)set('reminderList','No reminders saved yet.');
 for(const r of items){
  const row=document.createElement('div');row.className='entry reminder-entry';row.dataset.enabled=String(!!r.enabled);
  const text=document.createElement('div');text.className='entry-copy';text.textContent=r.kind[0].toUpperCase()+r.kind.slice(1)+' · '+r.time;
  const controls=document.createElement('div');controls.className='reminder-controls';
  const toggle=button(r.enabled?'ON':'OFF',async()=>{toggle.disabled=true;try{await api('/api/reminders/'+r.id,'PATCH',{enabled:!r.enabled});r.enabled=r.enabled?0:1;toggle.textContent=r.enabled?'ON':'OFF';toggle.setAttribute('aria-checked',String(!!r.enabled));row.dataset.enabled=String(!!r.enabled);set('reminderStatus',r.enabled?'Reminder resumed.':'Reminder paused.');}catch(e){set('reminderStatus',e.message);}finally{toggle.disabled=false;}});
  toggle.className='hardware-toggle';toggle.setAttribute('role','switch');toggle.setAttribute('aria-label',r.kind+' reminder at '+r.time);toggle.setAttribute('aria-checked',String(!!r.enabled));
  controls.append(toggle,button('Edit',()=>{editingReminder=r.id;const form=$('reminderForm');for(const name of ['kind','time'])form.elements[name].value=r[name];form.elements.enabled.checked=!!r.enabled;set('saveReminder','Save changes');$('cancelReminderEdit').hidden=false;set('reminderStatus','Editing reminder');form.scrollIntoView({block:'start'});}),button('Remove',async()=>{try{await api('/api/reminders/'+r.id,'DELETE');if(editingReminder===r.id)resetReminderEdit();await reminders();}catch(e){set('reminderStatus',e.message);}}));
  row.append(text,controls);$('reminderList').append(row);
 }
}catch(e){set('reminderList',e.message);}}
function resetReminderEdit(){editingReminder=null;set('saveReminder','Save reminder');$('cancelReminderEdit').hidden=true;$('reminderForm').reset();}
$('cancelReminderEdit').onclick=()=>{resetReminderEdit();set('reminderStatus','Ready for a new reminder.');};
$('reminderForm').onsubmit=async e=>{e.preventDefault();const form=e.target,b=form.querySelector('[type=submit]');b.disabled=true;$('cancelReminderEdit').disabled=true;try{const data=Object.fromEntries(new FormData(form));data.enabled=form.elements.enabled.checked;data.id=editingReminder||crypto.randomUUID();data.tone='direct';data.daysPerWeek=7;data.quietStart='22:00';data.quietEnd='07:00';data.timezone=Intl.DateTimeFormat().resolvedOptions().timeZone;await api(editingReminder?'/api/reminders/'+editingReminder:'/api/reminders',editingReminder?'PUT':'POST',data);set('reminderStatus',account?.push.schedulerActive?'Reminder saved.':'Saved. Sends once connected.');resetReminderEdit();await reminders();}catch(err){set('reminderStatus',err.message);}finally{b.disabled=false;$('cancelReminderEdit').disabled=false;}};

// --- Push device switch ---
const fromBase64=text=>Uint8Array.from(atob(text.replace(/-/g,'+').replace(/_/g,'/').padEnd(Math.ceil(text.length/4)*4,'=')),c=>c.charCodeAt(0));
const STATIC=globalThis.MYR5_STATIC===true,local=STATIC?await import('./static/local-reminders.mjs'):null;
async function syncDeviceSwitch(){
 if(STATIC){const on=local.notificationsOn(),ok='Notification' in window;$('notificationSwitch').setAttribute('aria-checked',String(on));set('notificationSwitch',on?'ON':'OFF');$('notificationSwitch').disabled=!ok;$('testPush').disabled=!on;set('pushStatus',local.statusText());return;}
 if(deviceBusy)return;
 try{
