    this.calibration.push({t,...sample});this.calibration=this.calibration.filter(v=>t-v.t<=1.1);
    this.setupProgress=Math.min(1,this.calibration.length/3,(t-this.calibration[0].t)/.7);this.setupReason='Hold steady';
