 const a3=(a,b,c)=>{const ids=[a,b,c],w=f.world;return w&&ids.every(i=>w[i]&&[w[i].x,w[i].y,w[i].z].every(Number.isFinite))?angle(w[a],w[b],w[c]):angle(f.p[a],f.p[b],f.p[c]);};
