// Pure date/goal math for the Home screen and Progress sheet. No DOM access.
// A "day" is always the local calendar day in the given IANA timezone.
const dayFormatters=new Map();
function localDay(when,timezone){
 let f=dayFormatters.get(timezone);
 if(!f){f=new Intl.DateTimeFormat('en-CA',{timeZone:timezone,year:'numeric',month:'2-digit',day:'2-digit'});dayFormatters.set(timezone,f);}
 return f.format(new Date(when));
}

const prevDay=day=>new Date(Date.parse(day+'T00:00:00Z')-86400000).toISOString().slice(0,10);
function totalsOn(day,logs,meals,timezone){
 const on=iso=>localDay(iso,timezone)===day,sum=kind=>logs.filter(l=>l.kind===kind&&on(l.logged_at)).reduce((total,l)=>total+l.value,0);
 return {waterOz:sum('water'),workoutMinutes:sum('workout'),proteinGrams:meals.filter(m=>on(m.eaten_at)).reduce((total,m)=>total+(m.protein||0),0)};
}

// Consecutive days with a workout logged, ending today - or yesterday if today has no workout yet.
// Steps by calendar day, not 24 h, so DST days never get skipped.
export function streak(logs,{now=Date.now(),timezone='UTC'}={}){
 const workoutDays=new Set(logs.filter(l=>l.kind==='workout').map(l=>localDay(l.logged_at,timezone)));
 let day=localDay(now,timezone),count=0;
 if(!workoutDays.has(day))day=prevDay(day);
 while(workoutDays.has(day)){count++;day=prevDay(day);}
 return count;
}

// Sums for "today" (local calendar day) across logs (water/workout) and meals (protein).
export const todayTotals=(logs,meals,{now=Date.now(),timezone='UTC'}={})=>totalsOn(localDay(now,timezone),logs,meals,timezone);

// One row per of the last 7 local days (oldest first), with each target's met/unmet flag.
export function last7Days(logs,meals,targets,{now=Date.now(),timezone='UTC'}={}){
 const days=[localDay(now,timezone)];while(days.length<7)days.unshift(prevDay(days[0]));
 return days.map(day=>{const t=totalsOn(day,logs,meals,timezone);return {day,
  workout:targets.sessionMinutes>0&&t.workoutMinutes>=targets.sessionMinutes,
  protein:targets.proteinGrams>0&&t.proteinGrams>=targets.proteinGrams,
  water:targets.waterOz>0&&t.waterOz>=targets.waterOz};});
}

// Latest weight log and the change since the closest log at or before 30 days ago.
export function weightSummary(logs,{now=Date.now(),days=30}={}){
 const weights=logs.filter(l=>l.kind==='weight').sort((a,b)=>Date.parse(a.logged_at)-Date.parse(b.logged_at));
 if(!weights.length)return {latest:null,changeOverDays:null};
 const latest=weights.at(-1).value;
 const cutoff=now-days*86400000;
 const past=[...weights].reverse().find(w=>Date.parse(w.logged_at)<=cutoff);
 return {latest,changeOverDays:past?Math.round((latest-past.value)*10)/10:null};
}

