training.mjs:
// MOM Inc. Fitness v2: camera training. Movements dialog -> hologram tutorial -> full-screen
// camera set -> set complete + rest timer. AGPL-3.0-or-later, like the accompanying app.
// hologram.mjs (and its `three` import) is loaded only inside openTutorial(), never here at
// module scope, so this file stays importable (and testable) with no browser/three present.
import {MovementSession, MOVEMENTS} from './movement-engine.mjs';
import {EXERCISES, FOCUS_GROUPS} from './exercise-library.mjs';
import {movementSetup} from './movement-setup.mjs';
import {openCamera, cameraFacing} from './camera.mjs';
import {CoachVoice, CueEvents, INTRO} from './coach.mjs';

const POSE_VERSION='0.10.14';
const VISION_URL=`https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@${POSE_VERSION}/vision_bundle.mjs`;
const WASM_URL=`https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@${POSE_VERSION}/wasm`;
const MODEL_URL='https://storage.googleapis.com/mediapipe-models/pose_landmarker/pose_landmarker_lite/float16/1/pose_landmarker_lite.task';

// --- Pure helpers (goal/rest math) -- exported for tests/training.test.mjs. No DOM here. ---
export function goalValue(m){return m.kind==='hold'?m.totalHold:m.kind==='pace'?m.active:m.count;}
export function goalReached(m,goal){
 const value=goalValue(m);
 if(value<goal)return false;
 if(m.kind==='pace'&&m.active<=0)return false; // a timed round needs observed hand movement, not just an unattended clock
 return true;
}
export function minutesFor(elapsedSeconds){return Math.max(1,Math.ceil((Number(elapsedSeconds)||0)/60));}
const UNIT_LABEL={hold:'s',pace:'s',steps:'steps',jumps:'jumps'};
export function detailFor(name,m){return `${name} · ${Math.round(goalValue(m))} ${UNIT_LABEL[m.kind]||'reps'}`;}
export function goalPresets(kind){
 if(kind==='hold'||kind==='pace')return [15,30,45,60];
 if(kind==='steps'||kind==='jumps')return [20,40,60,100];
 return [5,10,15,20];
}
// Breathing ring: 4s "in", 6s "out", repeating.
export function breathPhase(elapsedSeconds){const cycle=((elapsedSeconds%10)+10)%10;return cycle<4?'in':'out';}
export function restRemaining(totalSeconds,elapsedSeconds){return Math.max(0,totalSeconds-elapsedSeconds);}
export function extendRest(totalSeconds,by=30){return totalSeconds+by;}

const readLS=k=>{try{return localStorage.getItem(k);}catch{return null;}};
const writeLS=(k,v)=>{try{localStorage.setItem(k,v);}catch{}};
function loadGoal(id,kind){const presets=goalPresets(kind),saved=Number(readLS('myr5-goal-'+id));return presets.includes(saved)?saved:presets[1];}
function saveGoal(id,n){writeLS('myr5-goal-'+id,String(n));}
function loadRestSeconds(){const saved=Number(readLS('myr5-rest-seconds'));return [30,60,90].includes(saved)?saved:60;}
function saveRestSeconds(n){writeLS('myr5-rest-seconds',String(n));}
function clock(s){s=Math.max(0,Math.round(s));return Math.floor(s/60)+':'+String(s%60).padStart(2,'0');}

const MARKUP=`
<dialog id="trainingPanel" class="launch-panel training-panel" aria-labelledby="trainingTitle">
 <header><h2 id="trainingTitle">Movements</h2><button id="trainingClose" type="button">Close</button></header>
 <section id="trainingList" class="training-screen">
  <label class="library-filter" for="trainingFocus">Focus<select id="trainingFocus"></select></label>
  <div id="trainingCards" class="movement-cards" aria-label="Movement library"></div>
 </section>
 <section id="trainingTutorial" class="training-screen" hidden>
  <button id="trainingBack" type="button">Back</button>
  <h3 id="tutorialName"></h3>
  <div id="holoStage" role="img" aria-label="Exercise hologram preview. Drag to rotate."><p id="holoStatus" role="status"></p></div>
  <div class="holo-setup"><p id="tutorialPosition"></p><p id="tutorialPlacement"></p><p id="tutorialFrame" class="hint"></p><ul id="tutorialJoints"></ul></div>
  <p id="tutorialCaption" role="status" class="hint"></p>
  <p id="goalLabel">Goal</p>
  <div class="actions" id="tutorialGoals"></div>
  <button id="tutorialBegin" type="button" class="main-action">Begin</button>
 </section>
 <section id="trainingCamera" class="training-screen" hidden>
  <div class="camera-stage"><video id="trainVideo" playsinline muted></video><canvas id="trainCanvas"></canvas></div>
  <div id="trainCount" class="train-count" aria-live="polite">0 / 0</div>
  <p id="trainStatus" role="status"></p>
  <progress id="trainProgress" max="1" value="0"></progress>
  <div class="actions"><button id="trainStop" type="button">Stop</button><button id="trainFlip" type="button">Flip camera</button><button id="trainSound" type="button" class="hardware-toggle" role="switch" aria-checked="true">Sound ON</button></div>
 </section>
 <section id="trainingComplete" class="training-screen" hidden>
  <h3 id="completeSummary"></h3>
  <div class="rest-ring-wrap"><div id="restRing" class="rest-ring" aria-hidden="true"></div><p id="restCaption">Breathe in</p></div>
  <p id="restClock">1:00</p>
  <div class="actions" id="restPresets"><button type="button" data-rest="30">30 s</button><button type="button" data-rest="60">60 s</button><button type="button" data-rest="90">90 s</button></div>
  <div class="actions"><button id="restExtend" type="button">+30 s</button><button id="restSkip" type="button">Skip</button></div>
  <div class="actions"><button id="completeDone" type="button">Done</button><button id="completeAnother" type="button" class="main-action">Another set</button></div>
 </section>
</dialog>`;

export function mountTraining({onSetComplete}){
 const $=id=>document.getElementById(id);
 if(!$('trainingPanel'))document.body.insertAdjacentHTML('beforeend',MARKUP);
 const dialog=$('trainingPanel');

 const voice=new CoachVoice(text=>{
  const el=dialog.dataset.screen==='camera'?$('trainStatus'):$('tutorialCaption');
  if(el)el.textContent=text;
 });
 document.addEventListener('pointerdown',()=>voice.unlock(),{capture:true});
 if(!voice.available)$('trainSound').hidden=true;
 const cues=new CueEvents();

 let filter='legs';
 let selectedId=null,currentGoal=1;
 let session=null,camGen=0,rafId=0,tracker=null,draw=null,stream=null,poseApi=null,fileset=null,lastTime=-1,lastUi=0;
 let viewer=null,viewerGen=0;
 let restStartsSet=false,restTimerId=0,restTotal=60,restStart=0,restTenSpoken=false,restReadySpoken=false;

 function showScreen(name){
  dialog.dataset.screen=name;
  for(const id of ['trainingList','trainingTutorial','trainingCamera','trainingComplete'])$(id).hidden=id!=='training'+name[0].toUpperCase()+name.slice(1);
 }

 // --- Movements list ---
 for(const g of FOCUS_GROUPS){const o=document.createElement('option');o.value=g.id;o.textContent=g.name;$('trainingFocus').append(o);}
 $('trainingFocus').value=filter;
 for(const [id,ex] of Object.entries(EXERCISES)){
  const card=document.createElement('button');card.type='button';card.className='card-select';card.dataset.group=ex.group;card.setAttribute('aria-label',ex.name);
  const img=document.createElement('img');img.src='/models/previews/'+id+'.png';img.alt='';img.loading='lazy';img.decoding='async';img.width=512;img.height=512;
  const label=document.createElement('span');label.textContent=ex.name;
  card.append(img,label);card.onclick=()=>openTutorial(id);
  $('trainingCards').append(card);
 }
 function applyFilter(){filter=$('trainingFocus').value;for(const card of $('trainingCards').children)card.hidden=card.dataset.group!==filter;}
 $('trainingFocus').onchange=applyFilter;applyFilter();

 // --- Tutorial + hologram ---
 function renderGoalPresets(id,kind){
  currentGoal=loadGoal(id,kind);
  const presets=goalPresets(kind),unit='';$('goalLabel').textContent='Goal · '+(kind==='hold'||kind==='pace'?'seconds':kind==='steps'||kind==='jumps'?kind:'reps');
  $('tutorialGoals').replaceChildren(...presets.map(n=>{
   const b=document.createElement('button');b.type='button';b.textContent=n+unit;b.setAttribute('aria-pressed',String(n===currentGoal));
   b.onclick=()=>{currentGoal=n;saveGoal(id,n);for(const other of $('tutorialGoals').children)other.setAttribute('aria-pressed',String(other===b));};
   return b;
  }));
 }
 function releaseViewer(){viewerGen++;viewer?.dispose();viewer=null;}
 async function openTutorial(id){
  selectedId=id;voice.cancel();releaseViewer();showScreen('tutorial');
  const config=MOVEMENTS[id];
  $('tutorialName').textContent=config.name;
  const setup=movementSetup(EXERCISES[id]);
  $('tutorialPosition').textContent=setup.position;
  $('tutorialPlacement').textContent=setup.placement;
  $('tutorialFrame').textContent=setup.framing;
  $('tutorialJoints').replaceChildren(...setup.joints.map(name=>{const li=document.createElement('li');li.textContent=name;return li;}));
  renderGoalPresets(id,config.kind);
  $('holoStatus').hidden=false;$('holoStatus').textContent='Loading hologram…';
  voice.say(INTRO[id]||config.hint,{interrupt:true});
  const run=++viewerGen;
  try{
   const {createHologram}=await import('./hologram.mjs');
   if(run!==viewerGen||!dialog.open)return;
   const instance=await createHologram($('holoStage'),id);
   if(run!==viewerGen||!dialog.open){instance.dispose();return;}
   viewer=instance;$('holoStatus').hidden=true;
  }catch(error){if(run===viewerGen)$('holoStatus').textContent='Hologram could not load. '+error.message;}
 }
 $('trainingBack').onclick=()=>{voice.cancel();releaseViewer();showScreen('list');};
 $('tutorialBegin').onclick=()=>beginCamera();

 // --- Full-screen camera set ---
 function teardownCameraOnly(){
  cancelAnimationFrame(rafId);
  if(tracker){try{tracker.close();}catch{}tracker=null;}
  stream?.getTracks().forEach(t=>t.stop());stream=null;
  const video=$('trainVideo');if(video){video.pause();video.srcObject=null;}
  const canvas=$('trainCanvas');canvas?.getContext('2d')?.clearRect(0,0,canvas.width,canvas.height);
 }
 function formatCount(m){return `${Math.round(goalValue(m))} / ${currentGoal}`;}
 function renderCamera(m){$('trainCount').textContent=formatCount(m);$('trainStatus').textContent=m.message;$('trainProgress').value=Math.max(0,Math.min(1,goalValue(m)/currentGoal));}
 async function beginCamera(){
  const run=++camGen;teardownCameraOnly();releaseViewer();
  showScreen('camera');cues.reset();session=new MovementSession(selectedId);
  $('trainCount').textContent=`0 / ${currentGoal}`;$('trainProgress').value=0;$('trainStatus').textContent='Opening camera…';
  voice.say('Get into position.',{interrupt:true});
  try{
   if(!navigator.mediaDevices?.getUserMedia)throw new Error('Open the app over HTTPS to use the camera.');
   const choice=readLS('myr5-camera')==='environment'?'environment':'user',incoming=await openCamera(choice);
   if(run!==camGen){incoming.getTracks().forEach(t=>t.stop());return;}
   stream=incoming;const video=$('trainVideo');video.srcObject=stream;video.muted=true;await video.play();
   if(run!==camGen)return;
   const facing=cameraFacing(stream.getVideoTracks()[0],choice);
   video.style.transform=$('trainCanvas').style.transform=facing==='user'?'scaleX(-1)':'none';
   $('trainStatus').textContent='Loading tracker…';
   poseApi=poseApi||await import(VISION_URL);
   if(run!==camGen)return;
   fileset=fileset||await poseApi.FilesetResolver.forVisionTasks(WASM_URL);
   if(run!==camGen)return;
   // This CPU delegate is the measured baseline; some devices lose their WebGL context on GPU.
   const created=await poseApi.PoseLandmarker.createFromOptions(fileset,{baseOptions:{modelAssetPath:MODEL_URL,delegate:'CPU'},runningMode:'VIDEO',numPoses:1});
   if(run!==camGen){created.close();return;}
   tracker=created;draw=new poseApi.DrawingUtils($('trainCanvas').getContext('2d'));
   lastTime=-1;lastUi=0;
   $('trainStatus').textContent=MOVEMENTS[selectedId].hint;voice.say(MOVEMENTS[selectedId].hint,{interrupt:true});
   loop(run);
  }catch(error){
   if(run!==camGen)return;
   teardownCameraOnly();pauseToTutorial(error.name==='NotAllowedError'?'Allow camera access, then tap Begin.':error.message);
  }
 }
 function loop(run){
  if(run!==camGen||!tracker)return;
  try{
   const now=performance.now(),video=$('trainVideo'),canvas=$('trainCanvas');
   if(video.readyState>=2&&video.currentTime!==lastTime){
    lastTime=video.currentTime;const g=canvas.getContext('2d');
    if(canvas.width!==video.videoWidth||canvas.height!==video.videoHeight){canvas.width=video.videoWidth;canvas.height=video.videoHeight;}
    g.clearRect(0,0,canvas.width,canvas.height);
    const result=tracker.detectForVideo(video,now),p=result.landmarks[0]?.slice(0,27);
    if(p){draw.drawConnectors(p,poseApi.PoseLandmarker.POSE_CONNECTIONS.filter(b=>b.start<=26&&b.end<=26),{color:'#bc89ff',lineWidth:3});draw.drawLandmarks(p.filter(q=>q.visibility>=.45),{color:'#aaffd9',radius:3});draw.drawLandmarks(p.filter(q=>q.visibility<.45),{color:'#ffad66',radius:3});}
    const motion=session.update(p,now,video.videoWidth/video.videoHeight,result.worldLandmarks?.[0]);
    const cueMotion=['hold','pace'].includes(motion.kind)?{...motion,remaining:Math.max(0,currentGoal-(motion.kind==='hold'?motion.totalHold:motion.active))}:motion;
    for(const cue of cues.update(cueMotion,now))voice.say(cue.text,{key:cue.key,interrupt:cue.key==='complete'});
    if(goalReached(motion,currentGoal)){renderCamera(motion);finishSet(motion);return;}
    if(now-lastUi>=160){renderCamera(motion);lastUi=now;}
   }
   rafId=requestAnimationFrame(()=>loop(run));
  }catch(error){
   teardownCameraOnly();$('trainStatus').textContent='Tracking stopped: '+error.message;voice.say($('trainStatus').textContent,{interrupt:true});
  }
 }
 $('trainFlip').onclick=()=>{writeLS('myr5-camera',readLS('myr5-camera')==='environment'?'user':'environment');beginCamera();};
 $('trainStop').onclick=()=>{camGen++;teardownCameraOnly();voice.say('Stopped.',{interrupt:true});showScreen('list');};
 $('trainSound').onclick=()=>{const on=!voice.enabled;voice.setEnabled(on);$('trainSound').textContent='Sound '+(on?'ON':'OFF');$('trainSound').setAttribute('aria-checked',String(on));};

 function pauseToTutorial(message){showScreen('tutorial');$('holoStatus').hidden=false;$('holoStatus').textContent=message;voice.say(message,{interrupt:true});}

 // --- Set complete + rest timer ---
 function tickRest(){
  const elapsed=(Date.now()-restStart)/1000,remaining=restRemaining(restTotal,elapsed);
  $('restClock').textContent=clock(remaining);
  $('restCaption').textContent=breathPhase(elapsed)==='in'?'Breathe in':'Breathe out';
  if(remaining<=10&&remaining>0&&!restTenSpoken){restTenSpoken=true;voice.say('Ten seconds.',{key:'rest-ten',interrupt:true});}
  if(remaining<=0){
   clearInterval(restTimerId);restTimerId=0;
   if(!restReadySpoken){restReadySpoken=true;voice.say('Ready.',{key:'rest-ready',interrupt:true});navigator.vibrate?.(200);$('completeAnother').focus();}
  }
 }
 function startRest(total){
  clearInterval(restTimerId);restTotal=total;restStart=Date.now();restTenSpoken=false;restReadySpoken=false;saveRestSeconds(total);
  for(const b of $('restPresets').children)b.setAttribute('aria-pressed',String(Number(b.dataset.rest)===total));
  const ring=$('restRing');ring.style.animation='none';void ring.offsetWidth;ring.style.animation='';
  voice.say((restStartsSet?'Set complete. ':'')+'Rest. Breathe in slowly, and out.',{key:'rest-start',interrupt:true});restStartsSet=false;
  tickRest();restTimerId=setInterval(tickRest,200);
 }
 function stopRest(){clearInterval(restTimerId);restTimerId=0;}
 for(const b of $('restPresets').children)b.onclick=()=>startRest(Number(b.dataset.rest));
