  const elapsed=(Date.now()-restStart)/1000;restTotal=extendRest(restTotal,30);saveRestSeconds(restTotal);
  if(restRemaining(restTotal,elapsed)>10)restTenSpoken=false;
  restReadySpoken=false;
  if(!restTimerId)restTimerId=setInterval(tickRest,200);
  tickRest();
