 window.addEventListener('pagehide',teardown);
 document.addEventListener('visibilitychange',()=>{if(!document.hidden||!dialog.open)return;const inSet=dialog.dataset.screen==='camera';camGen++;teardownCameraOnly();releaseViewer();voice.cancel();if(inSet)pauseToTutorial('Paused. Tap Begin to continue.');});

